// intake.register.read — E2 AC6, SOP-DEL-01 §12. Generated by `pnpm gen:query`; acceptance cases added. The
// cards go through the real intake commands: submitted, returned, resubmitted, accepted.
import { afterAll, beforeAll, describe, expect, inject, it } from 'vitest';
import { aStaffActor, createFakeClock, createTestDatabase, type TestDatabase } from '@ocs/testing';
import { Forbidden, grantOf, openTestKernel, type TestKernel } from '../../kernel/index.ts';
import { createClient, createSite } from '../../org/index.ts';
import { decideIntake } from '../commands/decide-intake.ts';
import { saveHandoverCard } from '../commands/save-handover-card.ts';
import { submitHandoverCard } from '../commands/submit-handover-card.ts';
import { intakeRegister } from '../queries/intake-register.ts';
import { itemCodes } from '../rules/handover-checklist.ts';

const sales = aStaffActor({ roles: ['sales'] });
const director = aStaffActor({ roles: ['director'] });
const clock = createFakeClock(new Date('2026-11-16T09:00:00Z')); // Monday
let testDb: TestDatabase;
let t: TestKernel;
const sites: string[] = [];

const items = itemCodes.map((code) =>
  code.startsWith('F') ? { code, status: 'provided' } : { code, status: 'provided', value: 'in the folder' },
);
async function submit(siteId: string) {
  const content = { identification: { projectName: 'Counting', projectType: 'new' } };
  const input = { siteId, content, items, installsOrConfigures: true, newClientOrPlace: true };
  await t.kernel.execute(saveHandoverCard, sales, input, 'test');
  await t.kernel.execute(submitHandoverCard, sales, { siteId }, 'test');
}
const decide = (siteId: string, decision: string, extra: Record<string, unknown> = {}) =>
  t.kernel.execute(
    decideIntake,
    director,
    { siteId, decision, folderStandard: 'L', conditions: [], ...extra },
    'test',
  );

beforeAll(async () => {
  testDb = await createTestDatabase(inject('postgresUrl'));
  t = await openTestKernel(testDb.url, { clock: clock.now });
  t.grant(
    director,
    createClient.permission,
    createSite.permission,
    decideIntake.permission,
    intakeRegister.permission,
  );
  t.grant(sales, saveHandoverCard.permission, submitHandoverCard.permission);
  const a = await t.kernel.execute(
    createClient,
    director,
    { shortCode: 'CLIENTA', name: 'Client A' },
    'test',
  );
  const place = { countryCode: 'GB', cityCode: 'LON', cityName: 'London', name: 'Mall', standard: 'L' };
  for (let n = 0; n < 2; n += 1) {
    sites.push((await t.kernel.execute(createSite, director, { clientId: a.id, ...place }, 'test')).id);
  }
  const [one = '', two = ''] = sites;
  await submit(one); // Mon 16 Nov
  clock.advance({ hours: 24 });
  await decide(one, 'returned', { reasons: 'C3 point design unusable' }); // Tue 17
  clock.advance({ hours: 48 });
  await submit(one); // Thu 19
  await submit(two);
  clock.advance({ hours: 24 });
  await decide(one, 'accepted'); // Fri 20: 4 working days after Mon 16
});

afterAll(async () => {
  await t.close();
  await testDb.drop();
});

describe('intake.register.read', () => {
  it('is for the director, sponsor and management; not Sales', async () => {
    expect(grantOf(intakeRegister.permission)?.roles).toEqual(['director', 'management', 'sponsor']);
    await expect(t.kernel.read(intakeRegister, sales, {})).rejects.toBeInstanceOf(Forbidden);
  });

  it('logs every submission: date, decision, returns and working days to acceptance', async () => {
    const rows = await t.kernel.read(intakeRegister, director, {});
    expect(
      rows.map((r) => [r.version, r.submittedOn, r.decision, r.decidedOn, r.returns, r.daysToAcceptance]),
    ).toEqual([
      [1, '2026-11-16', 'returned', '2026-11-17', 0, null],
      [2, '2026-11-19', 'accepted', '2026-11-20', 1, 4],
      [1, '2026-11-19', 'pending', null, 0, null],
    ]);
  });

  it('filters by month of submission for the monthly review', async () => {
    expect(await t.kernel.read(intakeRegister, director, { month: '2026-11' })).toHaveLength(3);
    expect(await t.kernel.read(intakeRegister, director, { month: '2026-10' })).toEqual([]);
  });
});
